-- DDL of Foresight 1.0.0 (build 1.0.0.28.20261005) database.sqlite, PRAGMA user_version 5.
-- Schema only; no app data. sqlite_sequence is omitted because SQLite creates it itself.
CREATE TABLE "source_text_table" ("document_id" TEXT NOT NULL, "content" TEXT NOT NULL, "source_link" TEXT NOT NULL, "source_type" INTEGER NOT NULL, "timestamp" INTEGER NOT NULL, "last_embedding_time" INTEGER NOT NULL, "embedding_model_id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "document_name" TEXT NULL, "image_bytes" BLOB NULL, PRIMARY KEY ("document_id"));
CREATE TABLE "context_source_text_table" ("id" TEXT NOT NULL, "document_id" TEXT NOT NULL REFERENCES source_text_table (document_id) ON DELETE CASCADE, "content" TEXT NOT NULL, "model_id" TEXT NOT NULL, "tokens" INTEGER NOT NULL, "timestamp" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "event_document_table" ("event_id" TEXT NOT NULL, "event_name" TEXT NOT NULL, "document_id" TEXT NOT NULL, PRIMARY KEY ("event_id", "document_id"));
CREATE TABLE "event_insight_table" ("event_id" TEXT NULL, "timestamp" INTEGER NOT NULL, "event_name" TEXT NULL, "query" TEXT NOT NULL, "insight" TEXT NOT NULL, PRIMARY KEY ("event_id", "timestamp", "query"));
CREATE TABLE "event_transcript_table" ("event_id" TEXT NOT NULL, "timestamp" INTEGER NOT NULL, "event_name" TEXT NULL, "transcript" TEXT NOT NULL, "post_event_summarization" TEXT NULL, "calendar_event_id" TEXT NULL, "attendees" TEXT NULL, PRIMARY KEY ("event_id", "timestamp"));
CREATE TABLE "drive_file_subscription_table" ("file_id" TEXT NOT NULL, "subscribed_at" INTEGER NOT NULL, "state" TEXT NOT NULL, PRIMARY KEY ("file_id"));
CREATE TABLE "processed_uri_table" ("uri" TEXT NOT NULL, "document_id" TEXT NOT NULL, PRIMARY KEY ("uri"));
CREATE TABLE "nodes_table" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT UNIQUE NOT NULL, "node_type" TEXT NOT NULL, "summary" TEXT NULL, "first_seen" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "edges_table" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "source_id" INTEGER NOT NULL REFERENCES nodes_table (id), "target_id" INTEGER NOT NULL REFERENCES nodes_table (id), "relation_type" TEXT NOT NULL, "source_chunk_id" TEXT NOT NULL DEFAULT '', "weight" INTEGER NOT NULL DEFAULT 1, "last_updated" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "node_embeddings_table" ("node_id" INTEGER NOT NULL REFERENCES nodes_table (id), "embedding" BLOB NOT NULL, PRIMARY KEY ("node_id"));
CREATE TABLE "graph_rag_document_state_table" ("document_id" TEXT NOT NULL REFERENCES source_text_table (document_id) ON DELETE CASCADE, "state" TEXT NOT NULL, "error" TEXT NULL, "last_attempt" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("document_id"));
CREATE TABLE "contacts_table" ("email" TEXT NOT NULL, "name" TEXT NOT NULL, "timestamp" INTEGER NOT NULL, PRIMARY KEY ("email", "name"));
CREATE TABLE "notes_table" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "content" TEXT NOT NULL, "enhanced_content" TEXT NULL, "timestamp" INTEGER NOT NULL, "last_enhanced" INTEGER NULL, "last_manual_edit" INTEGER NULL, "enhancement_style" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "document_embeddings" ("document_id" TEXT NOT NULL REFERENCES source_text_table (document_id) ON DELETE CASCADE, "embedding" BLOB NOT NULL, "proj_x" REAL NOT NULL DEFAULT 0.0, "proj_y" REAL NOT NULL DEFAULT 0.0, "proj_z" REAL NOT NULL DEFAULT 0.0, "last_projected_time" INTEGER NOT NULL DEFAULT ((strftime('%s', 'now') * 1000)), PRIMARY KEY ("document_id"));
CREATE TABLE "document_edges" ("source_document_id" TEXT NOT NULL REFERENCES source_text_table (document_id) ON DELETE CASCADE, "target_document_id" TEXT NOT NULL REFERENCES source_text_table (document_id) ON DELETE CASCADE, "similarity_score" REAL NOT NULL, "edge_type" TEXT NOT NULL DEFAULT 'semantic_similarity', "created_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("source_document_id", "target_document_id", "edge_type"));
CREATE TABLE "document_clusters" ("cluster_id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "label" TEXT UNIQUE NOT NULL, "summary" TEXT NULL, "centroid_embedding" BLOB NULL, "center_proj_x" REAL NOT NULL DEFAULT 0.0, "center_proj_y" REAL NOT NULL DEFAULT 0.0, "radius" REAL NOT NULL DEFAULT 100.0);
CREATE TABLE "document_labels" ("document_id" TEXT NOT NULL REFERENCES source_text_table (document_id) ON DELETE CASCADE, "label_name" TEXT NOT NULL, "label_source" TEXT NOT NULL DEFAULT 'user_defined', "color_hex" TEXT NULL, "rationale" TEXT NULL, PRIMARY KEY ("document_id", "label_name"));
CREATE TABLE "document_entities" ("document_id" TEXT NOT NULL REFERENCES source_text_table (document_id) ON DELETE CASCADE, "entity" TEXT NOT NULL, "occurrences" INTEGER NOT NULL DEFAULT 1, PRIMARY KEY ("document_id", "entity"));
CREATE TABLE "document_entity_state" ("document_id" TEXT NOT NULL REFERENCES source_text_table (document_id) ON DELETE CASCADE, "content_hash" TEXT NOT NULL, "extractor_version" INTEGER NOT NULL, "last_attempt" INTEGER NOT NULL, "error" TEXT NULL, PRIMARY KEY ("document_id"));
